// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new StaxLPStaking(deployer, deployer);
    }

    function testFuzz_property(address fuzzCaller) public {
        vm.assume(fuzzCaller != deployer);
        vm.prank(fuzzCaller);
        address returned = c.owner();
        assertTrue(returned == deployer);
    }
}
